/* From Uiverse.io by Javierrocadev - Source: Javierrocadev - Tags: card, clip-path, shape, card hover, clip path animation */
.__UIV_SCOPE__ .card {
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .card * {
  position: absolute;
}

.__UIV_SCOPE__ .pentagon1 {
  width: 250px;
  height: 250px;
  background: #03045e;
  clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
  transition: all .3s ease-in-out;
}

.__UIV_SCOPE__ .pentagon2 {
  width: 220px;
  height: 220px;
  background: #0077b6;
  clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
  transition: all .4s ease-in-out;
}

.__UIV_SCOPE__ .pentagon3 {
  width: 190px;
  height: 190px;
  background: #00b4d8;
  clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
  transition: all .5s ease-in-out;
}

.__UIV_SCOPE__ .pentagon4 {
  width: 160px;
  height: 160px;
  background: #90e0ef;
  clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
  transition: all .6s ease-in-out;
}

.__UIV_SCOPE__ .pentagon5 {
  width: 130px;
  height: 130px;
  background: #caf0f8;
  clip-path: polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%);
  transition: all .7s ease-in-out;
}

.__UIV_SCOPE__ .card:hover .pentagon1, .__UIV_SCOPE__ .card:hover .pentagon2, .__UIV_SCOPE__ .card:hover .pentagon3, .__UIV_SCOPE__ .card:hover .pentagon4, .__UIV_SCOPE__ .card:hover .pentagon5 {
  transform: rotate(35deg);
}
